// Arma el texto por canal desde un solo payload — un nodo, no tres, para que
// la lógica de formato no diverja entre Email/WhatsApp/Llamada.
//
// El body llega envuelto por el Webhook node de n8n ($json.body es el JSON
// que mandó alert-notify.ts), mismo criterio que "Compose Telegram body" en
// wf-case-fanout.json.
const body = $input.first().json.body ?? $input.first().json;

const levelLabel = { critico: "CRÍTICO", advertencia: "ADVERTENCIA", info: "INFO" }[body.level] ?? body.level;
const trainTxt = body.train_code ? ` · ${body.train_code}` : "";

/** Escapa los 5 caracteres que TwiML (XML) interpreta, para <Say>. */
const escXml = (v) => String(v ?? "")
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;")
  .replace(/'/g, "&apos;");

const emailSubject = `[Tier0 · ${levelLabel}] ${body.rule_name}${trainTxt}`;
const emailText = `${body.message}\n\nActivo: ${body.train_code ?? "planta"}\nMétrica: ${body.metric} ${body.op === "lt" ? "<" : ">"} ${body.threshold}\nHora: ${body.ts}\n\n— Tier0, alerta automática (demo).`;

const whatsappText = `⚠️ *${levelLabel}* — ${body.rule_name}${trainTxt}\n${body.message}`;

// <Say> en español; una llamada corta y clara — el objetivo es que suene el
// teléfono y se entienda en 10 segundos, no dar el detalle completo.
const callTwiml = `<?xml version="1.0" encoding="UTF-8"?><Response><Say language="es-MX">`
  + `Alerta ${levelLabel === "CRÍTICO" ? "crítica" : "de planta"} de Tier0. `
  + `${escXml(body.rule_name)}. ${escXml(body.message)}`
  + `</Say></Response>`;

return [{
  json: {
    alert_id: body.alert_id,
    level: body.level,
    train_code: body.train_code,
    to_email: body.contact?.email || "",
    to_whatsapp: body.contact?.phone_whatsapp || "",
    to_voice: body.contact?.phone_voice || "",
    email_subject: emailSubject,
    email_text: emailText,
    whatsapp_text: whatsappText,
    call_twiml: callTwiml,
  },
}];
